cd /root/.openclaw/workspace && cat > /tmp/mockhub.js <<'EOF'
const http=require('http');
const fs=require('fs');
http.createServer((req,res)=>{
  let b='';req.on('data',d=>b+=d);req.on('end',()=>{
    fs.writeFileSync('/tmp/hub-records.jsonl',JSON.stringify({path:req.url,method:req.method,body:JSON.parse(b||'{}')})+'\n');
    res.writeHead(200,{'Content-Type':'application/json'});
    res.end(JSON.stringify({ok:true,recordId:'rec-12345',received:JSON.parse(b).entries.length}));
  });
}).listen(8899,'127.0.0.1',()=>console.log('mock hub on 8899'));
EOF
node /tmp/mockhub.js & sleep 1
node -e 'const fs=require("fs");const p="config/compliance-hub.json";const c=JSON.parse(fs.readFileSync(p));c.url="http://127.0.0.1:8899/v1/compliance/secret-env";fs.writeFileSync(p,JSON.stringify(c,null,2));'
./scripts/secret-env-compliance-sync.sh; echo "exit=$?"; echo "--- hub records ---"; cat /tmp/hub-records.jsonl; echo "--- log ---"; cat state/compliance-sync-last.json
